81	/// How the MHPCO's two kinds of modifier reach the premium: policy-wide
82	/// modifiers scale the policy base premium, while item-specific modifiers are
83	/// measured against their own item's base premium and are added alongside, so
84	/// a curse never surcharges the rest of the policy.
85	fn premium_before_fee(customer: &Customer, items: &[Item], previous_quotes: usize) -> f64 {
86	    let base = policy_base_premium(items);
87	    base + standing_adjustment(base, customer, previous_quotes) + item_risk_surcharges(items)
88	}
89	
90	pub fn quote(
91	    customer: &Customer,
92	    items: &[Item],
93	    previous_quotes: usize,
94	) -> Result<i64, Refusal> {
95	    if let Some(refusal) = refusal_to_insure(items) {
96	        return Err(refusal);
97	    }
98	    let premium = premium_before_fee(customer, items, previous_quotes);
99	    Ok(round_premium_in_mhpco_favor(premium) + PROCESSING_FEE)
100	}
