//! stated over admitted reports only: admissibility decides whether a report
//! is entertained at all, and matching decides which cover entertains it.

use crate::{Damage, Item};

/// The insured item a reported damage is matched to, if the policy covers one.
///
/// The MHPCO matches by item type alone: a report names a type, and the office
/// looks for that type among the covers on the policy.
fn matched_cover<'a>(insured: &'a [Item], damage: &Damage) -> Option<&'a Item> {
    insured
        .iter()
        .find(|item| item.item_type == damage.item_type)
}

/// The cover each reported damage of an admitted incident is read against, in
/// the order the incident reported them.
///
/// Admissibility has already established that the policy carries cover for
/// every report, so every report here finds its cover; the office would have
/// refused the incident otherwise.
pub(crate) fn covers_claimed_against<'a>(
    insured: &'a [Item],
    damages: &'a [Damage],
) -> impl Iterator<Item = (&'a Damage, &'a Item)> {
    damages.iter().map(move |damage| {
        let cover = matched_cover(insured, damage)
            .expect("an admitted incident reports only damage the policy covers");
        (damage, cover)
    })
}

/// How much cover of one item type the policy carries: the office reads a
/// damage report of a type against the covers of that type, so it can
/// entertain no more reports of a type than the policy has covers.
pub(crate) fn covers_of_type(insured: &[Item], item_type: &str) -> usize {
    insured
        .iter()
        .filter(|item| item.item_type == item_type)
        .count()
}
